			Status: config.StatusReady,
			Host:   "127.0.0.1",
			Port:   8080,
		},
	}

	header := ansi.Strip(m.renderHeader(100))
	if lines := strings.Count(header, "\n") + 1; lines != headerPanelHeight {
		t.Fatalf("unexpected header height: got %d want %d\n%s", lines, headerPanelHeight, header)
	}
