func TestLogViewArrowKeysScrollViewport(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.tabs.SelectID("logs")
	for i := 0; i < 12; i++ {
		m.logs = append(m.logs, config.LogEntry{
			Seq:    int64(i + 1),
			Stream: "stdout",
			Line:   "line",
		})
	}
	// Render once to set viewport size and content
	m.renderLogView(40, 6)
	m.logView.GotoBottom()
	if m.logView.YOffset() == 0 {
		t.Fatalf("expected initial scroll position to be at bottom")
	}
	before := m.logView.YOffset()

	next, _ := m.Update(tea.KeyPressMsg(tea.Key{Code: tea.KeyUp}))
	got := next.(*model)
	if got.logView.YOffset() >= before {
		t.Fatalf("up should scroll log viewport upward, got yoff=%d (before=%d)", got.logView.YOffset(), before)
	}

	before = got.logView.YOffset()
	next, _ = got.Update(tea.KeyPressMsg(tea.Key{Code: tea.KeyDown}))
	got = next.(*model)
	if got.logView.YOffset() <= before {
		t.Fatalf("down should scroll log viewport downward, got yoff=%d (before=%d)", got.logView.YOffset(), before)
	}
}

