			Stream: "stdout",
			Line:   "line",
		})
	}
	// Render once to set viewport size and content
	m.renderLogView(40, 6)
	m.logView.GotoBottom()
	if m.logView.YOffset() == 0 {
		t.Fatalf("expected initial scroll position to be at bottom")
	}
	before := m.logView.YOffset()

	next, _ := m.Update(tea.MouseWheelMsg(tea.Mouse{Button: tea.MouseWheelUp}))
	got := next.(*model)
	if got.logView.YOffset() >= before {
		t.Fatalf("mouse wheel up should scroll log viewport upward, got yoff=%d (before=%d)", got.logView.YOffset(), before)
	}

	before = got.logView.YOffset()
	got.tabs.SelectID("bookmarks")
	next, _ = got.Update(tea.MouseWheelMsg(tea.Mouse{Button: tea.MouseWheelDown}))
	got = next.(*model)
	if got.logView.YOffset() != before {
		t.Fatalf("mouse wheel should be ignored outside visible log view, got yoff=%d (before=%d)", got.logView.YOffset(), before)
	}
}

func TestNewLogsAutoFollowOnlyAtBottom(t *testing.T) {
