	got.logView.ScrollTo(0)
	yoffBefore := got.logView.YOffset()
	next, _ = got.Update(logsMsg{entries: []config.LogEntry{{
		Seq:    7,
		Stream: "stdout",
		Line:   "another line",
	}}})
	got = next.(*model)
	if got.logView.YOffset() != yoffBefore {
		t.Fatalf("expected viewport position to stay when scrolled up and tail mode disabled, got yoff=%d (before=%d)", got.logView.YOffset(), yoffBefore)
