func TestLogViewArrowKeysScrollViewport(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.tabs.SelectID("logs")
	for i := 0; i < 12; i++ {
		m.logs = append(m.logs, config.LogEntry{
			Seq:    int64(i + 1),
