		return m.cursorStyle.Render(" ")
	}
	first := clusters[0]
	remaining := ansi.Truncate(string(ph[first.end:]), avail-first.width, "")
	return m.cursorStyle.Render(string(ph[first.start:first.end])) + m.placeholderStyle.Render(remaining)
}

